export const PLACES: Place[] = [...CAFES, ...RESTAURANTS, ...SALONS, ...CLINICS];

export function getTopRated(limit = 6): Place[] {
  return [...PLACES].sort((a, b) => b.rating - a.rating).slice(0, limit);
}
export function getMostVisited(limit = 6): Place[] {
  return [...PLACES].sort((a, b) => b.visits - a.visits).slice(0, limit);
}
export function getByCategory(category: Category, limit?: number): Place[] {
  const filtered = PLACES.filter((p) => p.category === category);
  return limit ? filtered.slice(0, limit) : filtered;
}
export function getPlaceById(id: string): Place | undefined {
  return PLACES.find((p) => p.id === id);
}

export function getRegionCounts(): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const p of PLACES) {
    if (p.region) counts[p.region] = (counts[p.region] ?? 0) + 1;
  }
  return counts;
}

// Merges static PLACES with Supabase custom places (dedup by id)
export function mergePlaces(custom: Place[]): Place[] {
  const staticIds = new Set(PLACES.map((p) => p.id));
  const fresh = custom.filter((p) => !staticIds.has(p.id));
  return [...PLACES, ...fresh];
}